import React, { useEffect, useRef, useState } from 'react';
import PropTypes from 'prop-types';

const Slider = ({
  min = 0,
  max = 100,
  step = 1,
  initialValue = 50,
  heightPx = 40,
  minLabel = '',
  maxLabel = '',
  bubbleElement,
  bubbleLabel = '',
  className = '',
  minClassName = '',
  maxClassName = '',
  bubbleClassName = '',
  onChange,
}) => {
  // Ensure initialValue is a valid number
  const safeInitialValue = isNaN(initialValue) ? 50 : initialValue;
  const [value, setValue] = useState(safeInitialValue);
  const [isRtl, setIsRtl] = useState(false);
  const sliderRef = useRef(null);

  const handleChange = (e) => {
    const newValue = parseInt(e.target.value, 10);
    if (!isNaN(newValue)) {
      setValue(newValue);
      if (onChange) {
        onChange(newValue);
      }
    }
  };

  useEffect(() => {
    let node = sliderRef.current;
    while (node) {
      if (node.getAttribute('dir') === 'rtl') {
        setIsRtl(true);
        break;
      }
      node = node.parentElement;
    }
  }, []);

  useEffect(() => {
    // Only update state if initialValue is a valid number
    if (!isNaN(initialValue)) {
      setValue(initialValue);
    }
  }, [initialValue]);

  // Ensure value is a valid number for percentage calculation
  const safeValue = isNaN(value) ? min : value;
  const percentage = ((safeValue - min) / (max - min)) * 100;

  return (
    <div
      ref={sliderRef}
      className={`slider bg-base-200 mx-auto w-full max-w-md rounded-xl ${className}`}
      dir={isRtl ? 'rtl' : undefined}
    >
      <div className='relative' style={{ height: `${heightPx}px` }}>
        {/* Background track */}
        <div className='bg-base-300/40 absolute h-full w-full rounded-full'></div>
        {/* Filled portion */}
        <div
          className='bg-base-300 absolute h-full rounded-full'
          style={{
            width: percentage > 0 ? `calc(${percentage}% + ${heightPx / 2}px)` : '0px',
            [isRtl ? 'right' : 'left']: 0,
          }}
        ></div>
        {/* Min/Max labels */}
        <div className='absolute inset-0 flex items-center justify-between px-4 text-sm'>
          <span className={`ml-2 ${minClassName}`}>{minLabel}</span>
          <span className={`mr-2 ${maxClassName}`}>{maxLabel}</span>
        </div>
        {/* Thumb bubble */}
        <div
          className='pointer-events-none absolute top-0 z-10'
          style={{
            [isRtl ? 'right' : 'left']: `max(${heightPx / 2}px, calc(${percentage}%))`,
            transform: isRtl ? 'translateX(calc(50%))' : 'translateX(calc(-50%))',
            height: '100%',
          }}
        >
          <div
            className={`bg-base-200 flex h-full items-center justify-center rounded-full text-sm shadow-md ${bubbleClassName}`}
            style={{ width: `${heightPx}px` }}
          >
            {bubbleElement || bubbleLabel}
          </div>
        </div>
        <input
          type='range'
          min={min}
          max={max}
          step={step}
          value={isNaN(value) ? min : value}
          className='absolute inset-0 h-full w-full cursor-pointer opacity-0'
          onChange={handleChange}
        />
      </div>
    </div>
  );
};

Slider.propTypes = {
  min: PropTypes.number,
  max: PropTypes.number,
  step: PropTypes.number,
  initialValue: PropTypes.number,
  heightPx: PropTypes.number,
  minLabel: PropTypes.string,
  maxLabel: PropTypes.string,
  bubbleElement: PropTypes.node,
  bubbleLabel: PropTypes.string,
  className: PropTypes.string,
  minClassName: PropTypes.string,
  maxClassName: PropTypes.string,
  bubbleClassName: PropTypes.string,
  onChange: PropTypes.func,
};

export default Slider; 